import{_ as e,o as s,c as a,ag as o}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),r={name:"guide/quick-start.md"};function i(n,t,d,l,c,h){return s(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Get Claude Deck running and explore the dashboard in under 5 minutes.</p><h2 id="start-the-dev-servers" tabindex="-1">Start the Dev Servers <a class="header-anchor" href="#start-the-dev-servers" aria-label="Permalink to &quot;Start the Dev Servers&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/dev.sh</span></span></code></pre></div><p>This starts:</p><ul><li><strong>Backend</strong> at <code>http://localhost:8000</code> (API docs at <code>http://localhost:8000/docs</code>)</li><li><strong>Frontend</strong> at <code>http://localhost:5173</code></li></ul><p>Open <code>http://localhost:5173</code> in your browser.</p><h2 id="explore-the-dashboard" tabindex="-1">Explore the Dashboard <a class="header-anchor" href="#explore-the-dashboard" aria-label="Permalink to &quot;Explore the Dashboard&quot;">​</a></h2><p>The dashboard shows an overview of your selected provider and local project state. Claude Code still has the richest metrics; Codex surfaces focus on provider status, sessions, configuration, diagnostics, and inventory.</p><ul><li><strong>Projects</strong> — tracked project directories</li><li><strong>MCP Servers</strong> — configured server count</li><li><strong>Commands</strong> — available slash commands</li><li><strong>Plugins</strong> — installed plugins</li><li><strong>Hooks</strong> — automation hooks</li><li><strong>Permissions</strong> — allow/deny rules</li><li><strong>Sessions</strong> — conversation history with today/this week counts</li><li><strong>Context Window</strong> — highest context usage across active sessions</li></ul><p>Data is cached between page navigations and updates when you click the refresh button or switch projects.</p><h2 id="select-a-project" tabindex="-1">Select a Project <a class="header-anchor" href="#select-a-project" aria-label="Permalink to &quot;Select a Project&quot;">​</a></h2><p>Use the project selector in the sidebar to switch between projects. Many features show project-scoped data — MCP servers, commands, hooks, and permissions can differ between projects.</p><p>Use <strong>Discover Projects</strong> when you want Claude Deck to find projects from local agent state, or add a path manually with the directory browser.</p><h2 id="switch-providers" tabindex="-1">Switch Providers <a class="header-anchor" href="#switch-providers" aria-label="Permalink to &quot;Switch Providers&quot;">​</a></h2><p>Use the provider switcher in the sidebar to move between Claude Code and Codex CLI.</p><p>With Codex selected, start with:</p><ul><li><strong>Agent Bridge</strong> — find or start Codex tmux sessions</li><li><strong>Config</strong> — edit safe TOML settings, inspect profiles, and manage feature flags</li><li><strong>Backup</strong> — create a redacted Codex export</li></ul><h2 id="key-pages" tabindex="-1">Key Pages <a class="header-anchor" href="#key-pages" aria-label="Permalink to &quot;Key Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What You Can Do</th></tr></thead><tbody><tr><td><strong>MCP Servers</strong></td><td>Add servers, test connections, browse the MCP Registry</td></tr><tr><td><strong>Commands</strong></td><td>Create and edit slash commands</td></tr><tr><td><strong>Hooks</strong></td><td>Configure pre/post tool use automation</td></tr><tr><td><strong>Sessions</strong></td><td>Browse conversation transcripts</td></tr><tr><td><strong>Usage</strong></td><td>View token costs and billing blocks</td></tr><tr><td><strong>Agent Bridge</strong></td><td>Attach to live Claude Code and Codex terminals</td></tr></tbody></table><h2 id="production-build" tabindex="-1">Production Build <a class="header-anchor" href="#production-build" aria-label="Permalink to &quot;Production Build&quot;">​</a></h2><p>To build for production:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/build.sh</span></span></code></pre></div><p>This compiles the app frontend into <code>frontend/dist/</code> and the documentation site into <code>docs/.vitepress/dist/</code>. The backend serves the built app frontend automatically.</p><p>To preview the documentation site while editing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./scripts/docs-dev.sh</span></span></code></pre></div><p>Open <code>http://localhost:5174/docs/</code>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/docs/features/dashboard.html">Features</a> — detailed guides for each feature</li><li><a href="/docs/guide/architecture.html">Architecture</a> — how the app is structured</li><li><a href="/docs/api/">API Reference</a> — REST API documentation</li></ul>',29)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
